CREATE TABLE IF NOT EXISTS cms_records (collection TEXT NOT NULL,id TEXT NOT NULL,payload TEXT NOT NULL,PRIMARY KEY(collection,id));
CREATE TABLE IF NOT EXISTS cms_uploads (name TEXT PRIMARY KEY,type TEXT NOT NULL,data BLOB NOT NULL);
CREATE TABLE IF NOT EXISTS login_attempts (key TEXT PRIMARY KEY, attempts INTEGER NOT NULL, expires INTEGER NOT NULL);
INSERT OR IGNORE INTO cms_records(collection,id,payload) VALUES('artworks','1','{"id":"1","title":"Tanjore Fabric Painting","image":"/images/artwork/tanjore-fabric-painting.webp","alt":"Gold-on-blue Goddess in Tanjore style by Nishkala Krishna","medium":"Fabric, gold work","artForm":"Tanjore Fabric Painting","category":"Traditional","description":"A resplendent Goddess rendered in the classical Tanjore style — rich gold embellishments on deep blue fabric.","featured":true,"published":true,"sortOrder":1,"consentStatus":"approved"}');
INSERT OR IGNORE INTO cms_records(collection,id,payload) VALUES('artworks','2','{"id":"2","title":"Kerala Mural — Krishna & Radha","image":"/images/artwork/kerala-mural-painting.jpeg","alt":"Vivid Krishna and Radha in Kerala mural painting style","medium":"Acrylic on canvas","artForm":"Kerala Mural Painting","category":"Traditional","description":"A vibrant depiction of Krishna and Radha in the ancient Kerala mural tradition, full of movement and colour.","featured":true,"published":true,"sortOrder":2,"consentStatus":"approved"}');
INSERT OR IGNORE INTO cms_records(collection,id,payload) VALUES('artworks','3','{"id":"3","title":"Madhubani Peacock","image":"/images/artwork/madhubani-art.jpeg","alt":"Colourful peacock on black Madhubani painting signed Nish","medium":"Ink and colour on paper","artForm":"Madhubani Art","category":"Traditional","description":"A proud peacock surrounded by Madhubani floral motifs on a dramatic black ground.","featured":true,"published":true,"sortOrder":3,"consentStatus":"approved"}');
INSERT OR IGNORE INTO cms_records(collection,id,payload) VALUES('artworks','4','{"id":"4","title":"Zendoodle Portrait","image":"/images/artwork/zendoodle-art.jpeg","alt":"Black and white Zendoodle woman portrait — intricate patterns","medium":"Ink on paper","artForm":"Zendoodle Art","category":"Drawing & Patterns","description":"A serene woman''s profile rendered entirely in intricate Zendoodle patterns — thousands of tiny marks forming a whole.","featured":true,"published":true,"sortOrder":4,"consentStatus":"approved"}');
INSERT OR IGNORE INTO cms_records(collection,id,payload) VALUES('artworks','5','{"id":"5","title":"Acrylic — Kathakali Fusion","image":"/images/artwork/acrylic-painting.jpeg","alt":"Dramatic split-face Kathakali and Theyyam portrait in acrylic","medium":"Acrylic on canvas","artForm":"Acrylic Painting","category":"Painting","description":"A powerful split composition blending Kathakali and Theyyam — two great traditions of Kerala in one dramatic face.","featured":true,"published":true,"sortOrder":5,"consentStatus":"approved"}');
