INSERT OR IGNORE INTO cms_records(collection,id,payload) VALUES('artworks','9','{"id":"9","title":"Fabric Painting — Radha Krishna","image":"/images/artwork/fabric-painting.jpeg","alt":"Krishna and Radha on crimson fabric hoop","medium":"Fabric paint","artForm":"Fabric Painting","category":"Fabric & Crafts","description":"Young Krishna and Radha on deep crimson fabric — delicate, sweet and richly detailed.","featured":false,"published":true,"sortOrder":9,"consentStatus":"approved"}');
INSERT OR IGNORE INTO cms_records(collection,id,payload) VALUES('site-settings','settings','{"siteName":"Kalavridhi Arts","tagline":"Grow Your Dream","whatsapp":"918925626784","instagram":"https://www.instagram.com/kala_vridhi_arts/","founderName":"Nishkala Krishna","founderTitle":"Artist & Art Educator","yearsExperience":"20","shortBio":"For two decades, Nishkala Krishna has immersed herself in the rich world of traditional and contemporary Indian art. She brings a rare depth of creative and human understanding to every class she leads. From the meditative precision of Mandala and Zendoodle to the vibrant heritage of Kerala Mural and Madhubani, Nishkala teaches art not just as a skill, but as a joyful journey of self-expression. Her workshops welcome children and adults alike.","qualifications":["BCA","MSc Psychology","Diploma in Fashion Designing","Diploma in Fine Arts"],"heroHeading":"Where Creativity Blooms.","heroSubheading":"Discover traditional and contemporary art through classes and workshops led by Nishkala Krishna.","contactEmail":"","enableEnquiryForm":true,"metaDescription":"Explore traditional and contemporary art classes, original artworks and creative workshops with Nishkala Krishna at Kalavridhi Arts. Grow Your Dream."}');
